export const getGetPeeringUrl = (peeringId: string) => {
  return `https://compute.leaflow.cloud/api/v1/peerings/${peeringId}`;
};

/**
 * @summary Get peering
 */
export const getPeering = async (
  peeringId: string,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<getPeeringResponse> => {
  const res = await (fetchFn ?? fetch)(getGetPeeringUrl(peeringId), {
    ...options,
    method: "GET",
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: getPeeringResponse["data"] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as getPeeringResponse;
};

export type deletePeeringResponse202 = {
  data: PeeringResource;
  status: 202;
};

export type deletePeeringResponse409 = {
  data: ConflictResponse;
  status: 409;
};

export type deletePeeringResponseDefault = {
  data: Error;
  status: Exclude<HTTPStatusCodes, 202 | 409>;
};

export type deletePeeringResponseSuccess = deletePeeringResponse202 & {
  headers: Headers;
};
export type deletePeeringResponseError = (
  | deletePeeringResponse409
  | deletePeeringResponseDefault
) & {
  headers: Headers;
};

export type deletePeeringResponse = deletePeeringResponseSuccess | deletePeeringResponseError;

